use super::*;
use crate::companion_v1::{apply_fixture_control,fixture_snapshot,CompanionV1AudioChunk};
#[test]
fn owned_document_storage_backup_restore_and_precise_lifecycle(){
 let base=std::env::temp_dir().join(format!("companion-documents-{}",uuid::Uuid::new_v4()));let library=base.join("library");let restored=base.join("restored");let backups=base.join("backups");for p in [&library,&restored,&backups]{fs::create_dir_all(p).unwrap();}let library=library.canonicalize().unwrap();let restored=restored.canonicalize().unwrap();let state=base.join("sessions.json");
 let old_root=std::env::var_os("COMPANION_TYPE_RECORDING_DIR");let old_state=std::env::var_os("COMPANION_TYPE_STATE_PATH");std::env::set_var("COMPANION_TYPE_RECORDING_DIR",&library);std::env::set_var("COMPANION_TYPE_STATE_PATH",&state);
 let mut sound=denzic_host_audio_v1_core::wav::wav_header(32000).to_vec();sound.extend(vec![0;32000]);let audio=library.join("public-a.wav");let other_audio=library.join("public-b.wav");fs::write(&audio,&sound).unwrap();fs::write(&other_audio,&sound).unwrap();
 let mut snapshot=apply_fixture_control(fixture_snapshot(),serde_json::from_value(serde_json::json!({"action":"meetingLoadDemo"})).unwrap()).unwrap();snapshot.host.persistence.status="ready".into();snapshot.meeting.active=false;snapshot.device.recording=false;let mut row=snapshot.host.sessions.remove(0);row.id=format!("import-{}",uuid::Uuid::new_v4().simple());row.source="hostMicrophone".into();row.status="minutesReady".into();row.device_recording_key=None;row.device_recording_id=None;row.source_device_id=None;row.device_sha256=None;row.audio_path=Some(audio.to_string_lossy().into());row.audio_stored=true;row.retention.audio_cached=true;row.audio_bytes=sound.len() as u64;row.duration_ms=1000;row.meeting_tracks=None;row.chunks=vec![CompanionV1AudioChunk{id:"a".into(),path:row.audio_path.clone(),started_at:None,stopped_at:None,duration_ms:1000,bytes:sound.len() as u64,status:"sealed".into()}];row.document_context=Default::default();row.meeting_notes.clear();row.note_revision=0;row.bookmarks.clear();row.recovery=Default::default();let mut other=row.clone();other.id="other-public-document-session".into();other.audio_path=Some(other_audio.to_string_lossy().into());other.chunks[0].path=other.audio_path.clone();super::super::session_store::save(&state,&[row.clone(),other.clone()]).unwrap();
 let input=base.join("public-material.txt");let text="公开人工材料：预算12000元，Alex在周二核对。这不是会议结论。";fs::write(&input,text.as_bytes()).unwrap();let id=uuid::Uuid::new_v4().to_string();let import=||Request{session_id:row.id.clone(),document_id:id.clone(),expected_revision:0,change:Change::Import(input.clone())};
 let request=import();commit(&mut row,&request).unwrap();assert_eq!(row.document_context.revision,1);let original_path=original(&row,&id,1).unwrap();assert_eq!(fs::read(&original_path).unwrap(),text.as_bytes());commit(&mut row,&request).unwrap();assert_eq!(row.document_context.revision,1,"lost-reply original retry duplicates the entry");
 let sha=hash(text.as_bytes());let extracted=Extraction{schema:1,reader_version:"2026-11-10.1".into(),format:"txt".into(),source_sha256:sha.clone(),sections:vec![Section{id:"part-1".into(),label:"原文件文字".into(),text:text.into()}],warnings:vec![],characters:text.encode_utf16().count()};
 let index_before=fs::read(&state).unwrap();let mut wrong=extracted.clone();wrong.source_sha256="0".repeat(64);assert!(commit(&mut row,&Request{session_id:request.session_id.clone(),document_id:id.clone(),expected_revision:1,change:Change::Commit(wrong)}).is_err());assert_eq!(fs::read(&state).unwrap(),index_before);
 commit(&mut row,&Request{session_id:request.session_id.clone(),document_id:id.clone(),expected_revision:1,change:Change::Commit(extracted.clone())}).unwrap();assert_eq!(row.document_context.revision,2);assert_eq!(extraction(&row,&id,2).unwrap().sections[0].text,text);let ai=ai_document(&row,&id).unwrap();assert!(ai.id.starts_with("document:"));assert!(ai.title.starts_with("补充材料 · "));assert!(ai.text.contains("不是会议录音"));
 assert!(chunk(&row,&id,2,1).is_err());let chunk=chunk(&row,&id,2,0).unwrap();use base64::Engine;assert_eq!(base64::engine::general_purpose::STANDARD.decode(chunk["base64"].as_str().unwrap()).unwrap(),text.as_bytes());
 let other_input=base.join("other.txt");fs::write(&other_input,b"other recording material").unwrap();let other_id=uuid::Uuid::new_v4().to_string();let other_owner=other.id.clone();commit(&mut other,&Request{session_id:other_owner,document_id:other_id.clone(),expected_revision:0,change:Change::Import(other_input)}).unwrap();let other_file=original(&other,&other_id,1).unwrap();let other_bytes=fs::read(&other_file).unwrap();
 // The ordinary backup owns original documents and their extracted sidecars,
 // alongside the same unchanged audio and complete session metadata.
 snapshot.host.sessions=vec![row.clone(),other.clone()];let backup=super::super::library_backup::save(&snapshot,&library,&backups).unwrap();assert_eq!(backup.files,5);
 std::env::set_var("COMPANION_TYPE_RECORDING_DIR",&restored);let restored_rows=super::super::library_backup::restore_files(Path::new(&backup.path),&restored).unwrap();let restored_row=restored_rows.iter().find(|r|r.id==row.id).unwrap();assert_eq!(restored_row.document_context,row.document_context);assert_eq!(fs::read(original(restored_row,&id,2).unwrap()).unwrap(),text.as_bytes());assert_eq!(extraction(restored_row,&id,2).unwrap().sections[0].text,text);std::env::set_var("COMPANION_TYPE_RECORDING_DIR",&library);
 // Keep removal non-destructive. Only the existing recording purge owns cleanup.
 let selected_id=row.id.clone();commit(&mut row,&Request{session_id:selected_id,document_id:id.clone(),expected_revision:2,change:Change::Remove}).unwrap();assert!(original_path.exists());assert!(ai_document(&row,&id).is_err());assert_eq!(fs::read(&audio).unwrap(),sound);assert_eq!(fs::read(&other_file).unwrap(),other_bytes);
 let files=audio_artifacts::backup_files_at(&library,&[audio.to_string_lossy().into()]).unwrap();assert!(files.iter().any(|f|f.file==original_path.file_name().unwrap().to_str().unwrap()));assert!(files.iter().any(|f|f.purpose==Purpose::DocumentText));
 audio_artifacts::erase(&library,&[audio.to_string_lossy().into()],&[other_audio.to_string_lossy().into()]).unwrap();assert!(!original_path.exists());assert_eq!(fs::read(&other_audio).unwrap(),sound);assert_eq!(fs::read(&other_file).unwrap(),other_bytes);
 if let Some(value)=old_root{std::env::set_var("COMPANION_TYPE_RECORDING_DIR",value)}else{std::env::remove_var("COMPANION_TYPE_RECORDING_DIR")};if let Some(value)=old_state{std::env::set_var("COMPANION_TYPE_STATE_PATH",value)}else{std::env::remove_var("COMPANION_TYPE_STATE_PATH")};
}
